fn word(pack: Pack, index: usize) []const u8 {
    if (index < 17) return pack.f[index];
    if (index < 35) return pack.v[index - 17];
    if (index < 60) return pack.p[index - 35];
    if (index < 75) return pack.t[index - 60];
    if (index < 92) return pack.m[index - 75];
    return pack.e[index - 92];
}
pub fn row(comptime key: Key) [count][]const u8 {
    @setEvalBranchQuota(2000000);
    var result: [count][]const u8 = undefined;
    for (0..count) |i| result[i] = word(data[i], @intFromEnum(key));
    return result;
}
pub fn decorate(comptime key: Key, comptime prefix: []const u8, comptime suffix: []const u8) [count][]const u8 {
    @setEvalBranchQuota(2000000);
    const base = row(key);
    var result: [count][]const u8 = undefined;
    inline for (0..count) |i| result[i] = std.fmt.comptimePrint("{s}{s}{s}", .{ prefix, base[i], suffix });
    return result;
}
test "all 30 language packs have 100 nonempty UTF-8 phrases" {
    try std.testing.expectEqual(@as(usize, count), data.len);
    try std.testing.expectEqual(@as(usize, 100), @typeInfo(Key).Enum.fields.len);
    for (data) |pack| {
        for (0..100) |i| {
            const value = word(pack, i);
            try std.testing.expect(value.len > 0);
            try std.testing.expect(std.unicode.utf8ValidateSlice(value));
        }
    }
}
